 <html lang="en">
 <head>
   <meta charset="utf-8">
   <meta name="viewport" content="width=device-width, initial-scale=1">
   <title>Support Contact Form</title>
   <style>
     :root {
       color-scheme: light;
       --bg: #f3f7fb;
       --surface: rgba(255, 255, 255, 0.88);
       --surface-solid: #ffffff;
       --text: #172033;
       --muted: #5d6b82;
       --border: #d9e2ef;
       --border-strong: #93a4bf;
       --accent: #2458d3;
       --accent-strong: #1d49b0;
       --danger: #c53434;
       --shadow: 0 24px 60px rgba(23, 32, 51, 0.12);
