 <body>
   <main class="page">
     <section class="support-card" aria-labelledby="support-title">
       <div class="support-card__header">
         <h1 id="support-title">Contact support</h1>
         <p class="lede">Send us your details and we&apos;ll get back to you as soon as possible.</p>
         <p class="required-note"><span class="required-mark" aria-hidden="true">*</span> Required fields</p>
       </div>

       <p class="form-status" id="form-status" aria-live="polite"></p>

       <form id="support-form" novalidate>
         <div class="form-field">
           <label for="full-name">Full name <span class="required-mark" aria-hidden="true">*</span></label>
           <input
             id="full-name"
             name="fullName"
             type="text"
             autocomplete="name"
             required
             aria-describedby="full-name-error"
           >
           <p class="field-error" id="full-name-error" hidden></p>
         </div>

         <div class="form-field">
           <label for="email-address">Email address <span class="required-mark" aria-hidden="true">*</span></label>
           <input
             id="email-address"
             name="email"
             type="email"
             autocomplete="email"
             required
             aria-describedby="email-address-error"
           >
           <p class="field-error" id="email-address-error" hidden></p>
         </div>

         <div class="form-field">
           <label for="phone-number">Phone number</label>
           <input
             id="phone-number"
             name="phone"
             type="tel"
             autocomplete="tel"
             inputmode="tel"
             aria-describedby="phone-number-help phone-number-error"
           >
           <p class="field-help" id="phone-number-help">Use a number we can reach, like +1 555 123 4567 or (555) 123-4567.</p>
           <p class="field-error" id="phone-number-error" hidden></p>
         </div>

         <div class="actions">
           <button type="submit">Send message</button>
         </div>
       </form>
     </section>
   </main>

   <script>
     (() => {
       const form = document.getElementById('support-form');
       const status = document.getElementById('form-status');
       const fields = [
         {
           input: document.getElementById('full-name'),
           error: document.getElementById('full-name-error'),
           validate: (input) => input.value.trim() ? '' : 'Error: Enter your full name.'
         },
         {
           input: document.getElementById('email-address'),
           error: document.getElementById('email-address-error'),
           validate: (input) => {
             if (!input.value.trim()) return 'Error: Enter your email address.';
             return input.validity.typeMismatch ? 'Error: Enter a valid email address.' : '';
           }
         },
         {
           input: document.getElementById('phone-number'),
           error: document.getElementById('phone-number-error'),
           validate: () => ''
         }
       ];

       const describedBy = (input, ids) => {
         const list = Array.from(new Set(ids.filter(Boolean)));
         if (list.length) {
           input.setAttribute('aria-describedby', list.join(' '));
         } else {
           input.removeAttribute('aria-describedby');
         }
       };

       const setError = (field, message) => {
         const { input, error } = field;
         if (message) {
           error.textContent = message;
           error.hidden = false;
           input.setAttribute('aria-invalid', 'true');
           describedBy(input, [
             input.id === 'phone-number' ? 'phone-number-help' : null,
             error.id
           ]);
         } else {
           error.textContent = '';
           error.hidden = true;
           input.removeAttribute('aria-invalid');
           describedBy(input, input.id === 'phone-number' ? ['phone-number-help'] : []);
         }
       };

       const validateField = (field) => {
         const message = field.validate(field.input);
         setError(field, message);
         return !message;
       };

       const validateAll = () => {
         let firstInvalid = null;
         let valid = true;

         fields.forEach((field) => {
           if (!validateField(field)) {
             valid = false;
             if (!firstInvalid) firstInvalid = field.input;
           }
         });

         return { valid, firstInvalid };
       };

       fields.forEach((field) => {
         field.input.addEventListener('input', () => {
           if (field.input.getAttribute('aria-invalid') === 'true') {
             validateField(field);
           }
           status.textContent = '';
         });

         field.input.addEventListener('blur', () => {
           if (field.input.value.trim()) {
             validateField(field);
           }
         });
       });

       form.addEventListener('submit', (event) => {
         event.preventDefault();
         status.textContent = '';

         const { valid, firstInvalid } = validateAll();

         if (!valid) {
           firstInvalid.focus();
           return;
         }

         status.textContent = 'Message ready to send.';
         form.reset();
         fields.forEach((field) => setError(field, ''));
       });
     })();
   </script>
